(
    '00000000-0000-0000-0000-000000000005', 'avelora-signature', 'luxury', 'Avelora Signature', 'Sri Lanka', 11, 
    '/Photos/Other sections/Velora Luxe Main photo.webp', 'Luxury', 'Luxury, Thoughtfully Curated', 
    'Luxury • Culture • Nature', 
    'A refined journey designed for travellers seeking Sri Lanka''s most iconic destinations while enjoying carefully selected boutique hotels, private experiences, and a seamless travel pace.', 
    'Handpicked Stays\nA curated collection of Sri Lanka’s finest boutique hotels and heritage properties from Geoffrey Bawa-inspired jungle retreats and restored colonial tea bungalows to luxury safari lodges and refined coastal villas. Final hotel selection will be confirmed based on availability and your preferences.', 
    ARRAY['Cultural Icons', 'Tea Country', 'Private Safari', 'Coastal Retreats'], 
    ARRAY['Stay at architecturally iconic boutique properties', 'Private scenic train carriage through tea country', 'Exclusive early access to heritage sites', 'Personal chauffeur and naturalist guide'], 
    ARRAY['Luxury travellers', 'Special occasions', 'Boutique hotel enthusiasts', 'Couples seeking refined experiences'], 
    ARRAY['Airport', 'Negombo', 'Sigiriya', 'Kandy', 'Tea Country', 'Ella', 'Yala', 'South Coast', 'Departure'], 
    '[{"lat": 7.18, "lng": 79.89, "name": "Airport", "description": "VIP arrival, Colombo"}, {"lat": 7.21, "lng": 79.84, "name": "Negombo", "description": "Coastal town, first night"}, {"lat": 7.96, "lng": 80.76, "name": "Sigiriya", "description": "Geoffrey Bawa resort & rock fortress"}, {"lat": 7.29, "lng": 80.63, "name": "Kandy", "description": "Private temple viewing & luxury estate"}, {"lat": 6.9, "lng": 80.59, "name": "Tea Country", "description": "Private train carriage & colonial bungalow"}, {"lat": 6.87, "lng": 81.05, "name": "Ella", "description": "Nine Arches Bridge & mountain scenery"}, {"lat": 6.37, "lng": 81.52, "name": "Yala", "description": "Ultra-luxury tented safari lodge"}, {"lat": 6.03, "lng": 80.21, "name": "South Coast", "description": "Premier beachfront villa & Galle Fort"}]'::jsonb, 
    ARRAY['Private chauffeur-guide for the entire journey', 'All luxury hotel accommodation (10 nights)', 'Daily breakfast and dinner (half board basis)', 'All private air-conditioned transport', 'Private scenic train carriage', 'Exclusive Yala safari with naturalist', 'All entrance fees and experiences', '24/7 concierge support'], 
    ARRAY['International flights', 'Visa Fees and travel insurance', 'Meals not specified', 'Personal expenses, spa treatments, and tips', 'Optional helicopter transfers', 'Early check-in and late check-out unless specified'], 
    '[{"day": 1, "title": "VIP Arrival", "highlights": ["VIP clearance", "Boutique hotel", "Relax after your journey"], "description": "Premium airport welcome. Transfer to a luxury boutique hotel in Colombo. Evening fine dining experience."}, {"day": 2, "title": "Negambo to Dambulla", "highlights": ["Journey to Cultural Triangle", "Geoffrey Bawa resort", "Jungle luxury"], "description": "Journey to the Cultural Triangle and check into your hotel, an iconic property inspired by Geoffrey Bawa."}, {"day": 3, "title": "Dambulla", "highlights": ["Exclusive Sigiriya access", "Historian guide", "Spa afternoon"], "description": "Private early access to Sigiriya Rock Fortress with an expert historian guide. Afternoon luxury spa treatment."}, {"day": 4, "title": "Dambulla to Kandy", "highlights": ["Chauffeured drive", "Private temple viewing", "Luxury estate"], "description": "Chauffeured drive to Kandy. Private viewing at the Temple of the Tooth. Stay at a secluded luxury estate."}, {"day": 5, "title": "Kandy to Nuwara Eliya", "highlights": ["Private train carriage", "Colonial bungalow", "High tea"], "description": "Board a private carriage on the scenic train to the tea country. Check into a restored colonial tea planter''s bungalow."}, {"day": 6, "title": "Nuwara Eliya to Ella", "highlights": ["Master tea tasting", "Gourmet picnic", "Estate walks"], "description": "Private tea tasting with a master blender. Gourmet picnic lunch amidst the rolling tea fields."}, {"day": 7, "title": "Ella", "highlights": ["Adventure to wild", "Ultra-luxury lodge", "Wilderness immersion"], "description": "Adventure to the wild. Arrive at an ultra-luxury tented safari lodge bordering Yala National Park."}, {"day": 8, "title": "Ella to Yala", "highlights": ["Private jeep safari", "Expert naturalist", "Bush sundowners"], "description": "Exclusive full-day private jeep safari in Yala with a specialized naturalist. Sundowners in the bush."}, {"day": 9, "title": "Yala to Weligama", "highlights": ["Premier beach resort", "Private villa", "Ocean views"], "description": "Transfer to a premier beachfront resort near Galle. Private villa check-in. Evening at leisure."}, {"day": 10, "title": "Weligama", "highlights": ["Beach relaxation", "Galle Fort twilight tour", "Chef''s tasting menu"], "description": "Relaxed beach day. Evening private guided tour of Galle Fort followed by a curated chef''s tasting menu."}, {"day": 11, "title": "Weligama to Airport", "highlights": ["Luxury breakfast", "Private transfer", "VIP departure"], "description": "Final luxury breakfast. Private transfer to the airport with priority boarding assistance."}]'::jsonb, 
    ARRAY['/Photos/Other sections/Velora Luxe Main photo.webp', '/Photos/Other sections/Destination Tea.jpeg', '/Photos/Other sections/Destination Dambulla.jpg', '/Photos/Hero Slide 2 Cape Weligama.jpg', '/Photos/Other sections/Collection page.jpeg'], 
    true
)
