INSERT INTO public.packages (
    id, slug, category, title, location, days, image_url, tag, subtitle, 
    travel_style, description, accommodation, highlights, why_special, 
    perfect_for, route, route_coords, included, not_included, 
    itinerary, gallery_images, is_active
) VALUES 
(
    '00000000-0000-0000-0000-000000000008', 'avelora-wellness', 'wellness', 'Avelora Wellness', 'Sri Lanka', 15, 
    '/Photos/Other sections/Velora Serene new.avif', 'Wellness', 'A Gentle Wellness Journey Through Sri Lanka', 
    'Wellness • Ayurveda • Nature', 
    'A carefully designed wellness journey combining authentic Ayurveda treatments, peaceful countryside retreats, and gentle cultural exploration. This itinerary balances wellness and slow travel experiences for a calm and restorative journey.', 
    'Handpicked Stays\nStay in a carefully curated collection of tranquil retreats and boutique properties from beachfront Ayurveda sanctuaries in Bentota to peaceful countryside lodges, cool hill country escapes, and nature-inspired stays in Sri Lanka''s cultural heartland. Final hotel selection will be confirmed based on availability and your preferences.', 
    ARRAY['Ayurveda', 'Gentle Exploration', 'Slow Travel'], 
    ARRAY['Authentic Ayurveda under medical supervision', 'Gentle, unhurried pace designed for wellbeing', 'Peaceful countryside and wellness properties', 'Dosha-specific nutrition and treatments', 'Digital detox and mindful travel experiences'], 
    ARRAY['Senior travellers', 'Wellness seekers', 'Slow travellers', 'Solo retreats'], 
    ARRAY['Airport', 'Negombo', 'Bentota (Ayurveda)', 'Wellawaya', 'Nuwara Eliya', 'Kandy', 'Habarana', 'Departure'], 
    '[{"lat": 7.18, "lng": 79.89, "name": "Airport", "description": "Gentle arrival, Colombo"}, {"lat": 7.21, "lng": 79.84, "name": "Negombo", "description": "Wellness resort, first night"}, {"lat": 6.43, "lng": 80.01, "name": "Bentota", "description": "Authentic Ayurveda centre"}, {"lat": 6.73, "lng": 81.1, "name": "Wellawaya", "description": "Countryside wellness stay"}, {"lat": 6.97, "lng": 80.77, "name": "Nuwara Eliya", "description": "Mountain wellness estate & tea healing"}, {"lat": 7.29, "lng": 80.63, "name": "Kandy", "description": "Highland sanctuary & sacred sounds"}, {"lat": 8.04, "lng": 80.76, "name": "Habarana", "description": "Final wellness retreat"}]'::jsonb, 
    ARRAY['Private chauffeur for all transfers', 'All wellness resort accommodation (14 nights)', 'Daily Ayurvedic treatments as prescribed', 'All meals (Dosha-specific cuisine, half board basis)', 'Doctor consultations and wellness plans', 'Yoga and meditation sessions', 'All entrance fees for gentle excursions', '24/7 wellness support'], 
    ARRAY['International flights', 'Visa Fees and travel insurance', 'Additional spa treatments not in plan', 'Personal expenses and tips', 'Optional cultural excursions', 'Early check-in and late check-out unless specified'], 
    '[{"day": 1, "title": "Airport to Negombo", "highlights": ["Soft arrival", "Beachfront hotel", "Rest and recovery"], "description": "Arrive in Sri Lanka and meet your private chauffeur-guide. Transfer to Negombo and settle into your beachfront hotel, allowing time to relax and recover after your journey."}, {"day": 2, "title": "Negombo to Bentota", "highlights": ["Ayurveda retreat", "Wellness consultation", "Begin treatments"], "description": "Travel south to Bentota and check into your Ayurveda retreat. Begin your personalised wellness programme with a consultation and gentle introduction to treatments."}, {"day": 3, "title": "Bentota", "highlights": ["Ayurvedic treatments", "Herbal meals", "Rest and reflection"], "description": "Enjoy your daily wellness routine, including personalised Ayurvedic treatments, nourishing herbal meals, and time for rest and reflection."}, {"day": 4, "title": "Bentota", "highlights": ["Detoxification", "Rejuvenation", "Body and mind balance"], "description": "Continue your tailored Ayurveda programme focused on relaxation, detoxification, and restoring balance to body and mind."}, {"day": 5, "title": "Bentota", "highlights": ["Healing treatments", "Meditation", "Peaceful surroundings"], "description": "A day dedicated to healing, with treatments, meditation, and quiet time within the peaceful surroundings of your retreat."}, {"day": 6, "title": "Bentota", "highlights": ["Personalised treatments", "Coastal calm", "Wellness at your pace"], "description": "Follow your personalised treatment plan, with time to unwind, read, or simply enjoy the calm coastal setting."}, {"day": 7, "title": "Bentota", "highlights": ["Continued treatments", "Mindful relaxation", "Restore and renew"], "description": "Deepen your wellness experience through continued treatments and mindful relaxation."}, {"day": 8, "title": "Bentota", "highlights": ["Final Ayurveda day", "Programme completion", "Wellness absorption"], "description": "Your final full day at the retreat, allowing time to fully absorb the benefits of your personalised wellness programme."}, {"day": 9, "title": "Bentota to Wellawaya", "highlights": ["Countryside journey", "Village walks", "Nature reconnection"], "description": "Journey inland to Wellawaya, a peaceful rural setting. Enjoy gentle village walks and time to reconnect with nature."}, {"day": 10, "title": "Wellawaya", "highlights": ["Meditation sessions", "Meditation centre", "Mindfulness and nature"], "description": "A slow day with optional meditation sessions and a visit to a serene meditation centre near Ella."}, {"day": 11, "title": "Wellawaya to Nuwara Eliya", "highlights": ["Hill country", "Tea plantations", "Mountain air"], "description": "Travel into Sri Lanka''s hill country. Enjoy cooler temperatures, scenic tea plantations, and fresh mountain air."}, {"day": 12, "title": "Nuwara Eliya to Kandy", "highlights": ["Temple of the Tooth", "Botanical gardens", "Cultural performances"], "description": "Continue to Kandy. Visit the Temple of the Tooth and explore the botanical gardens, with optional cultural performances in the evening."}, {"day": 13, "title": "Kandy to Habarana", "highlights": ["Elephant safari", "Cultural sites", "Cultural heartland"], "description": "Travel to Habarana. Experience a gentle elephant safari and explore nearby cultural sites."}, {"day": 14, "title": "Habarana", "highlights": ["Anuradhapura", "Polonnaruwa", "Ancient cities"], "description": "Optional visits to Anuradhapura or Polonnaruwa, or enjoy a relaxed day surrounded by nature."}, {"day": 15, "title": "Habarana to Airport", "highlights": ["Airport transfer", "Wellness conclusion", "Departure"], "description": "Transfer to the airport for your onward journey, concluding your wellness experience in Sri Lanka."}]'::jsonb, 
    ARRAY['/Photos/Other sections/Velora Serene new.avif', '/Photos/Other sections/Peradeniya Garden.jpeg', '/Photos/Other sections/Rice Field.jpeg', '/Photos/Other sections/new-6.jpg', '/Photos/Other sections/new-7.webp'], 
    true
)
ON CONFLICT (id) DO UPDATE SET
    slug = EXCLUDED.slug,
    category = EXCLUDED.category, title = EXCLUDED.title, location = EXCLUDED.location, days = EXCLUDED.days,
    image_url = EXCLUDED.image_url, tag = EXCLUDED.tag, subtitle = EXCLUDED.subtitle, travel_style = EXCLUDED.travel_style,
    description = EXCLUDED.description, accommodation = EXCLUDED.accommodation, highlights = EXCLUDED.highlights,
    why_special = EXCLUDED.why_special, perfect_for = EXCLUDED.perfect_for, route = EXCLUDED.route,
    route_coords = EXCLUDED.route_coords, included = EXCLUDED.included, not_included = EXCLUDED.not_included,
    itinerary = EXCLUDED.itinerary, gallery_images = EXCLUDED.gallery_images, is_active = EXCLUDED.is_active;

INSERT INTO public.packages (
    id, slug, category, title, location, days, image_url, tag, subtitle, 
    travel_style, description, accommodation, highlights, why_special, 
    perfect_for, route, route_coords, included, not_included, 
