) VALUES 
(
    '00000000-0000-0000-0000-000000000010', 'avelora-serendipity', 'adventure', 'Avelora Discovery', 'Sri Lanka', 8, 
    '/Photos/Other sections/Hill Country.jpg', 'Signature', 'A Perfect Introduction to the Island', 
    'Culture • Nature • Scenic Landscapes', 
    'An unforgettable journey through Sri Lanka''s cultural heartland, misty hill country, and tropical coastline. This carefully curated itinerary blends ancient heritage sites, scenic landscapes, and boutique hotels to create a seamless introduction to the island.', 
    'Handpicked Stays\nA curated collection of Sri Lanka’s finest boutique hotels and heritage properties from Geoffrey Bawa-inspired jungle retreats and restored colonial tea bungalows to luxury safari lodges and refined coastal villas. Final hotel selection will be confirmed based on availability and your preferences.', 
    ARRAY['Heritage', 'Highlands', 'Wildlife', 'Southern Coast'], 
    ARRAY['Carefully balanced pace with no rushed travel days', 'Handpicked boutique and luxury hotels', 'Private chauffeur-guided travel throughout', 'Flexible experiences tailored to your travel style', 'Seamless coordination from arrival to departure'], 
    ARRAY['First-time visitors', 'Couples', 'Families', 'Culture & scenic travel lovers'], 
    ARRAY['Airport', 'Sigiriya', 'Kandy', 'Nuwara Eliya', 'Ella', 'Yala', 'Galle', 'Departure'], 
    '[{"lat": 7.18, "lng": 79.89, "name": "Airport", "description": "Bandaranaike International Airport, arrival"}, {"lat": 7.96, "lng": 80.76, "name": "Sigiriya", "description": "Ancient rock fortress & cultural triangle"}, {"lat": 7.29, "lng": 80.63, "name": "Kandy", "description": "Sacred city & Temple of the Tooth"}, {"lat": 6.97, "lng": 80.77, "name": "Nuwara Eliya", "description": "Misty tea country highlands"}, {"lat": 6.87, "lng": 81.05, "name": "Ella", "description": "Nine Arches Bridge & mountain scenery"}, {"lat": 6.37, "lng": 81.52, "name": "Yala", "description": "Wildlife safari & leopard territory"}, {"lat": 6.05, "lng": 80.22, "name": "Galle", "description": "UNESCO Fort & southern coast"}]'::jsonb, 
    ARRAY['Private chauffeur-guide for the entire journey', 'All hotel accommodation (7 nights)', 'Daily breakfast and dinner (half board basis)', 'All private air-conditioned transport', 'Entrance fees to all listed sites', 'Yala National Park safari', 'Scenic train journey (subject to availability)', '24/7 local support'], 
    ARRAY['International flights', 'Visa Fees and travel insurance', 'Meals not specified in the itinerary', 'Personal expenses and tips', 'Optional activities', 'Early check-in and late check-out unless specified'], 
    '[{"day": 1, "title": "Arrival & Negombo", "highlights": ["Airport welcome", "Coastal relaxation", "Relax after your journey"], "description": "Welcome to Sri Lanka. Meet your private chauffeur-guide and transfer to your hotel in Negombo."}, {"day": 2, "title": "Negambo to Sigiriya", "highlights": ["Dambulla Cave Temple", "Jungle resort", "Cultural immersion"], "description": "Drive to the Cultural Triangle. Visit the ancient Dambulla Cave Temple. Relax at your jungle resort."}, {"day": 3, "title": "Sigiriya to Kandy", "highlights": ["Sigiriya Rock", "Spice garden tour", "Arrival in Kandy"], "description": "Early morning climb of Sigiriya Rock Fortress. Travel to Kandy, stopping at a traditional spice garden en route."}, {"day": 4, "title": "Kandy to Nuwara Eliya", "highlights": ["Temple of the Tooth", "Scenic highland drive", "Tea factory visit"], "description": "Visit the Temple of the Tooth. Journey up into the misty tea plantations of Nuwara Eliya. Tea factory tour."}, {"day": 5, "title": "Nuwara Eliya to Ella → Yala", "highlights": ["Scenic train ride", "Ella mountain views", "Journey to the wild"], "description": "Board the iconic scenic train to Ella. Enjoy the breathtaking views. Meet your driver and continue to Yala."}, {"day": 6, "title": "Yala to Galle to Ahungalla", "highlights": ["Yala dawn safari", "Wildlife spotting", "Southern coast arrival"], "description": "Dawn jeep safari in Yala National Park searching for leopards. Travel along the beautiful southern coast to your beach resort."}, {"day": 7, "title": "Ahungalla", "highlights": ["Galle Fort tour", "Colonial history", "Beach relaxation"], "description": "Morning guided walk through the UNESCO-listed Galle Fort. Afternoon at leisure on the beach."}, {"day": 8, "title": "Ahungalla to Airport", "highlights": ["Final beach walk", "Airport transfer", "Farewell to Sri Lanka"], "description": "Enjoy your final morning by the ocean before transferring to the airport for your departure flight."}]'::jsonb, 
    ARRAY['/Photos/Other sections/serendipity-new-1.webp', '/Photos/Other sections/Nuwara Eliya.jpeg', '/Photos/Other sections/Destination Ella.jpeg', '/Photos/Other sections/Destination Galle.jpeg', '/Photos/Other sections/serendipity-new-5.webp', '/Photos/Other sections/Hill Country.jpg'], 
    true
)
ON CONFLICT (id) DO UPDATE SET
    slug = EXCLUDED.slug,
    category = EXCLUDED.category, title = EXCLUDED.title, location = EXCLUDED.location, days = EXCLUDED.days,
    image_url = EXCLUDED.image_url, tag = EXCLUDED.tag, subtitle = EXCLUDED.subtitle, travel_style = EXCLUDED.travel_style,
    description = EXCLUDED.description, accommodation = EXCLUDED.accommodation, highlights = EXCLUDED.highlights,
    why_special = EXCLUDED.why_special, perfect_for = EXCLUDED.perfect_for, route = EXCLUDED.route,
    route_coords = EXCLUDED.route_coords, included = EXCLUDED.included, not_included = EXCLUDED.not_included,
