INSERT INTO public.packages (
    id, slug, category, title, location, days, image_url, tag, subtitle, 
    travel_style, description, accommodation, highlights, why_special, 
    perfect_for, route, route_coords, included, not_included, 
    itinerary, gallery_images, is_active
) VALUES 
(
    '00000000-0000-0000-0000-000000000011', 'grand-explorer', 'adventure', 'Grand Explorer', 'Sri Lanka', 20, 
    '/Photos/Other sections/Our Journeys_Classic Discovery.jpeg', 'Explorer', 'Sri Lanka''s Grand Adventure', 
    'Adventure • Culture • Nature • Beach', 
    'A comprehensive 20-day journey exploring Sri Lanka''s ancient kingdoms, lush rainforests, remote east-coast beaches, mountain landscapes, and wildlife reserves. Designed for travellers who want to experience the island in depth.', 
    'Handpicked Stays Across Sri Lanka\nA carefully curated collection of boutique hotels, eco-lodges, and luxury resorts selected for their location, comfort, and authentic character. From rainforest retreats to east coast beaches and southern luxury resorts, each stay enhances your journey. Final hotel selection will be confirmed based on availability and your preferences.', 
    ARRAY['Ancient Kingdoms', 'Surf Coast', 'Wildlife Safaris', 'Hill Country'], 
    ARRAY['The most comprehensive Sri Lanka journey available', 'Explore regions most travellers never see', 'Blend of east coast, west coast, and highland experiences', 'Both cultural immersion and wildlife adventure', 'Private chauffeur-guide for the entire journey'], 
    ARRAY['Active travellers', 'Returning visitors to Sri Lanka', 'Multi-region explorers', 'Photography enthusiasts'], 
    ARRAY['Airport', 'Bentota', 'Kitulgala', 'Kandy', 'Sigiriya', 'Trincomalee', 'Pasikuda', 'Arugam Bay', 'Ella', 'Hambantota', 'Departure'], 
    '[{"lat": 7.18, "lng": 79.89, "name": "Airport", "description": "International arrival, Colombo"}, {"lat": 6.43, "lng": 80.01, "name": "Bentota", "description": "Coastal relaxation & water sports"}, {"lat": 6.99, "lng": 80.42, "name": "Kitulgala", "description": "White-water rafting & jungle"}, {"lat": 7.29, "lng": 80.63, "name": "Kandy", "description": "Temple of the Tooth & Botanical Gardens"}, {"lat": 7.96, "lng": 80.76, "name": "Sigiriya", "description": "Rock fortress & ancient ruins"}, {"lat": 8.57, "lng": 81.23, "name": "Trincomalee", "description": "East coast beaches & whale watching"}, {"lat": 7.92, "lng": 81.55, "name": "Pasikuda", "description": "Pristine east coast lagoon"}, {"lat": 6.84, "lng": 81.84, "name": "Arugam Bay", "description": "World-class surf coast"}, {"lat": 6.87, "lng": 81.05, "name": "Ella", "description": "Nine Arches Bridge & highlands"}, {"lat": 6.12, "lng": 81.12, "name": "Hambantota", "description": "Southern coast & departure"}]'::jsonb, 
    ARRAY['Private chauffeur-guide for 20 days', 'All hotel accommodation (19 nights)', 'Daily breakfast and dinner (half board basis)', 'All private air-conditioned transport', 'Yala and Minneriya safari experiences', 'All entrance fees to listed sites', '24/7 local support'], 
    ARRAY['International flights', 'Visa Fees and travel insurance', 'Meals not specified in the itinerary', 'Personal expenses, surf lessons, and tips', 'Optional water sports activities', 'Early check-in and late check-out unless specified'], 
    '[{"day": 1, "title": "Airport to Bentota", "highlights": ["Airport welcome", "Bentota transfer", "Beach & River Life"], "description": "Arrive in Sri Lanka and travel to Bentota. Unwind on the beach, explore the lagoon, or enjoy optional water sports and a Madu River safari."}, {"day": 2, "title": "Bentota", "highlights": ["Beach day", "Water sports", "Madu River safari"], "description": "A full day to enjoy Bentota. Beach relaxation, water sports, and a Madu River boat safari through the mangroves."}, {"day": 3, "title": "Bentota to Kitulgala", "highlights": ["White-water rafting", "Jungle walks", "Rainforest adventure"], "description": "Journey inland to Kitulgala. Experience white-water rafting, jungle walks, waterfalls, and optional birdwatching in a lush rainforest setting."}, {"day": 4, "title": "Kitulgala", "highlights": ["Waterfall exploration", "Birdwatching", "Nature walks"], "description": "A full day of rainforest adventure. Explore waterfalls, enjoy optional birdwatching and nature walks through the lush jungle."}, {"day": 5, "title": "Kitulgala to Kandy", "highlights": ["Temple of the Tooth", "Botanical gardens", "Dance performance"], "description": "Travel to Kandy, Sri Lanka''s cultural capital. Visit the Temple of the Tooth, stroll through botanical gardens, and enjoy a traditional dance performance."}, {"day": 6, "title": "Kandy", "highlights": ["Botanical Gardens", "Local markets", "Cultural capital"], "description": "Explore Kandy further. Visit the Royal Botanical Gardens, browse local markets, and experience the city''s spiritual heart."}, {"day": 7, "title": "Kandy to Sigiriya", "highlights": ["Sigiriya Rock", "Dambulla Cave Temple", "Ancient Kingdoms"], "description": "Explore the Cultural Triangle. Climb Sigiriya Rock Fortress, visit Dambulla Cave Temple, enjoy an elephant safari, and experience village life by the lake."}, {"day": 8, "title": "Sigiriya", "highlights": ["Polonnaruwa ruins", "Minneriya safari", "Village life"], "description": "Continue exploring the ancient kingdoms. Visit Polonnaruwa ruins, enjoy an elephant gathering safari at Minneriya, and experience traditional village life."}, {"day": 9, "title": "Sigiriya to Trincomalee", "highlights": ["Koneswaram Temple", "Nilaveli beach", "East Coast"], "description": "Head to the east coast. Visit Koneswaram Temple and Fort Frederick, relax on Nilaveli beach, and enjoy optional snorkelling at Pigeon Island."}, {"day": 10, "title": "Trincomalee", "highlights": ["Pigeon Island", "Whale watching", "Marine life"], "description": "A full day on the east coast. Beach relaxation, optional whale watching, and snorkelling at Pigeon Island."}, {"day": 11, "title": "Trincomalee", "highlights": ["Fort Frederick", "Local markets", "Seafood"], "description": "Continue enjoying the east coast. Visit Fort Frederick, explore local markets, and enjoy fresh seafood."}, {"day": 12, "title": "Trincomalee to Pasikuda", "highlights": ["Pasikuda transfer", "Turquoise waters", "Calm coastal escape"], "description": "Travel along the east coast to Pasikuda, known for its shallow turquoise waters. Enjoy a relaxed beach day with optional kayaking or snorkelling."}, {"day": 13, "title": "Pasikuda to Arugam Bay", "highlights": ["Arugam Bay", "Lagoon safaris", "Laid-back coast"], "description": "Continue south to Arugam Bay. Enjoy optional surfing, lagoon safaris, elephant sightings at Lahugala, and birdwatching in Kumana National Park."}, {"day": 14, "title": "Arugam Bay", "highlights": ["Surfing", "Lagoon safari", "Coastal living"], "description": "Morning surf or beach relaxation. Afternoon lagoon boat safari and exploring the surf town lifestyle."}, {"day": 15, "title": "Arugam Bay", "highlights": ["Kumana NP", "Birdwatching", "Beach time"], "description": "Optional visit to Kumana National Park for birdwatching, or enjoy another day of surf and sand."}, {"day": 16, "title": "Arugam Bay to Ella", "highlights": ["Nine Arches Bridge", "Little Adam''s Peak", "Hill country"], "description": "Travel to Ella in the hill country. Visit the Nine Arches Bridge, hike Little Adam''s Peak, or enjoy optional adventure activities."}, {"day": 17, "title": "Ella", "highlights": ["Ravana Falls", "Tea estates", "Mountain air"], "description": "Continue exploring Ella. Hike to Ravana Falls, visit local tea estates, and soak in the mountain atmosphere."}, {"day": 18, "title": "Ella to Hambantota", "highlights": ["Yala safari", "Leopard tracking", "Wildlife & Southern Coast"], "description": "Head south for a safari experience in Yala National Park, followed by time to relax at your coastal resort."}, {"day": 19, "title": "Hambantota", "highlights": ["Beach relaxation", "Galle Fort", "Southern coast"], "description": "Relaxed day at your southern coast resort. Optional visit to Galle Fort or whale watching."}, {"day": 20, "title": "Hambantota to Airport", "highlights": ["Airport transfer", "Island memories", "Departure"], "description": "Transfer to the airport for your onward journey, concluding your exploration of Sri Lanka."}]'::jsonb, 
    ARRAY['/Photos/Other sections/Our Journeys_Classic Discovery.jpeg', '/Photos/Other sections/Polonnaruwa.jpeg', '/Photos/Other sections/Anuradhapura.jpeg', '/Photos/Other sections/Destination Ella.jpeg', '/Photos/Other sections/Bentota water sports.webp', '/Photos/Other sections/Section 2 _ Coast.jpeg'], 
    true
)
