) VALUES 
(
    '00000000-0000-0000-0000-000000000016', 'avelora-honeymoon', 'honeymoon', 'Avelora Romance', 'Sri Lanka', 12, 
    '/Photos/Other sections/Velora Luxury Honeymoon new.webp', 'Romance', 'A Romantic Escape Through Sri Lanka', 
    'Romantic • Scenic • Luxury', 
    'A carefully designed honeymoon experience combining Sri Lanka''s ancient wonders, misty tea estates, scenic mountain landscapes, wildlife safaris, and luxury coastal retreats.', 
    'Handpicked Stays\nA curated collection of romantic boutique hotels and luxury retreats from private jungle villas with plunge pools to colonial tea estate bungalows and oceanfront suites with sunset views. Final hotel selection will be confirmed based on availability and your preferences.', 
    ARRAY['Romantic Stays', 'Tea Country', 'Safari', 'Beach Sunsets'], 
    ARRAY['Romantic candlelit dinners at every destination', 'Private couple experiences throughout', 'Handpicked honeymoon-friendly boutique hotels', 'Blend of adventure, culture, and relaxation', 'Seamless private travel with no group tours'], 
    ARRAY['Honeymoon couples', 'Anniversary travellers', 'Romantic getaways', 'Couples seeking luxury & adventure'], 
    ARRAY['Airport', 'Negombo', 'Sigiriya', 'Tea Country', 'Ella', 'Yala', 'South Coast', 'Departure'], 
    '[{"lat": 7.18, "lng": 79.89, "name": "Airport", "description": "VIP arrival, Colombo"}, {"lat": 7.21, "lng": 79.84, "name": "Negombo", "description": "Boutique beach hotel & candlelit dinner"}, {"lat": 7.96, "lng": 80.76, "name": "Sigiriya", "description": "Private jungle villa with plunge pool"}, {"lat": 6.9, "lng": 80.59, "name": "Tea Country", "description": "Colonial bungalow & mountain romance"}, {"lat": 6.87, "lng": 81.05, "name": "Ella", "description": "Nine Arches Bridge at golden hour"}, {"lat": 6.37, "lng": 81.52, "name": "Yala", "description": "Luxury safari lodge & wilderness sundowners"}, {"lat": 6.03, "lng": 80.21, "name": "South Coast", "description": "Beachfront resort & Galle Fort"}]'::jsonb, 
    ARRAY['Private chauffeur-guide for 12 days', 'All luxury accommodation (11 nights)', 'Daily breakfast and romantic dinner (half board basis)', 'All private air-conditioned transport', 'Private Yala safari experience', 'Scenic train journey (subject to availability)', 'Entrance fees to all listed sites', 'Honeymoon amenities at each hotel', '24/7 local support'], 
    ARRAY['International flights', 'Visa Fees and travel insurance', 'Meals not specified in the itinerary', 'Personal expenses, spa treatments, and tips', 'Optional water sports and activities', 'Early check-in and late check-out unless specified'], 
    '[{"day": 1, "title": "Arrival & Negombo", "highlights": ["VIP arrival", "Beach hotel", "Candlelit dinner"], "description": "VIP airport welcome. Transfer to a boutique beach hotel in Negombo. Candlelit welcome dinner by the ocean."}, {"day": 2, "title": "Journey to Sigiriya", "highlights": ["Private villa", "Plunge pool", "Jungle sunset"], "description": "Drive to the Cultural Triangle. Check into a private jungle villa with plunge pool. Sunset cocktails."}, {"day": 3, "title": "Sigiriya & Ancient Wonders", "highlights": ["Sigiriya sunrise", "Village cycling", "Romantic picnic"], "description": "Sunrise climb of Sigiriya Rock Fortress. Afternoon couples'' village cycling experience."}, {"day": 4, "title": "Sacred Kandy", "highlights": ["Temple of the Tooth", "Dance performance", "Spice garden"], "description": "Visit the Temple of the Tooth in Kandy. Private Kandyan dance performance. Evening spice garden walk."}, {"day": 5, "title": "Into the Tea Country", "highlights": ["Tea country drive", "Colonial bungalow", "High tea"], "description": "Scenic drive up to the misty tea plantations. Check into a restored colonial tea planter''s bungalow. High tea together."}, {"day": 6, "title": "Mountain Romance", "highlights": ["Tea tasting", "Couples'' spa", "Fireside dinner"], "description": "Private tea estate walk and tasting. Couples'' spa treatment. Dinner by the fireplace."}, {"day": 7, "title": "Scenic Train to Ella", "highlights": ["Scenic train ride", "Nine Arches Bridge", "Mountain views"], "description": "Board the iconic scenic train through tea country to Ella. Visit the Nine Arches Bridge at golden hour."}, {"day": 8, "title": "Ella to Yala", "highlights": ["Little Adam''s Peak", "Safari lodge", "Bush dinner"], "description": "Morning hike to Little Adam''s Peak. Afternoon drive to Yala. Check into a luxury safari lodge."}, {"day": 9, "title": "Safari & Sunsets", "highlights": ["Dawn safari", "Leopard spotting", "Wilderness sundowners"], "description": "Dawn jeep safari in Yala National Park. Afternoon at leisure. Sundowner cocktails in the wilderness."}, {"day": 10, "title": "Southern Coast Arrival", "highlights": ["Beach resort", "Ocean views", "Private dinner"], "description": "Transfer to a luxury beachfront resort on the southern coast. Afternoon at leisure. Private beach dinner."}, {"day": 11, "title": "Galle Fort & Leisure", "highlights": ["Galle Fort", "Couples'' spa", "Farewell dinner"], "description": "Morning guided walk through Galle Fort. Afternoon spa and relaxation. Farewell romantic dinner."}, {"day": 12, "title": "Departure", "highlights": ["Beach sunrise", "Airport transfer", "Farewell"], "description": "Final morning by the ocean. Private transfer to the airport with lasting honeymoon memories."}]'::jsonb, 
    ARRAY['/Photos/Other sections/Velora Luxury Honeymoon new.webp', '/Photos/Other sections/Section 2 Honeymoon.jpg', '/Photos/Other sections/Destination Mirissa.jpeg', '/Photos/Other sections/new-3.webp', '/Photos/Other sections/new-4.webp'], 
    true
)
ON CONFLICT (id) DO UPDATE SET
