INSERT INTO public.packages (
    id, slug, category, title, location, days, image_url, tag, subtitle, 
    travel_style, description, accommodation, highlights, why_special, 
    perfect_for, route, route_coords, included, not_included, 
    itinerary, gallery_images, is_active
) VALUES 
(
    '00000000-0000-0000-0000-000000000017', 'avelora-wild', 'adventure', 'Avelora Wild', 'Sri Lanka', 17, 
    '/Photos/Other sections/Journey_Velora Wild new.jpg', 'Wildlife', 'Sri Lanka''s Ultimate Wildlife Expedition', 
    'Wildlife • Birding • Nature', 
    'A comprehensive wildlife journey across Sri Lanka''s most diverse ecosystems, from wetlands and coastal lagoons to remote rainforests and mountain landscapes. Designed for wildlife lovers, photographers, and nature travellers seeking immersive safaris and birding experiences.', 
    'Handpicked Stays\nA curated collection of Sri Lanka’s finest boutique hotels and heritage properties from Geoffrey Bawa-inspired jungle retreats and restored colonial tea bungalows to luxury safari lodges and refined coastal villas. Final hotel selection will be confirmed based on availability and your preferences.', 
    ARRAY['Wetlands', 'National Parks', 'Rainforests', 'Mountain Ecosystems'], 
    ARRAY['Sri Lanka''s most comprehensive wildlife journey', 'Expert naturalist guides at every national park', 'Cover all major ecosystems, wetlands to mountains', 'Exceptional birding opportunities (400+ species)', 'Remote wilderness camps and eco-lodges'], 
    ARRAY['Wildlife enthusiasts', 'Photographers', 'Birders', 'Nature travellers seeking immersive safaris'], 
    ARRAY['Airport', 'Chilaw', 'Wilpattu', 'Trincomalee', 'Arugam Bay', 'Gal Oya', 'Nuwara Eliya', 'Sinharaja', 'Kitulgala', 'Departure'], 
    '[{"lat": 7.18, "lng": 79.89, "name": "Airport", "description": "International arrival, Colombo"}, {"lat": 7.57, "lng": 79.8, "name": "Chilaw", "description": "Wetlands & lagoon birding"}, {"lat": 8.35, "lng": 80.05, "name": "Wilpattu", "description": "Leopard & sloth bear safaris"}, {"lat": 8.57, "lng": 81.23, "name": "Trincomalee", "description": "Whale watching & Pigeon Island"}, {"lat": 6.84, "lng": 81.84, "name": "Arugam Bay", "description": "Kumana NP & surf coast"}, {"lat": 7.17, "lng": 81.33, "name": "Gal Oya", "description": "Swimming elephants boat safari"}, {"lat": 6.97, "lng": 80.77, "name": "Nuwara Eliya", "description": "Horton Plains & cloud forest"}, {"lat": 6.41, "lng": 80.49, "name": "Sinharaja", "description": "UNESCO rainforest & endemic birds"}, {"lat": 6.99, "lng": 80.42, "name": "Kitulgala", "description": "White-water rafting & jungle"}]'::jsonb, 
    ARRAY['Private chauffeur and naturalist guide', 'All accommodation (16 nights)', 'Daily breakfast and dinner (half board basis)', 'All private air-conditioned transport', 'All national park entrance fees', 'All safari jeep experiences', 'Boat safaris and nature walks', 'Sinharaja rainforest trekking permits', '24/7 wildlife support team'], 
    ARRAY['International flights', 'Visa Fees and travel insurance', 'Meals not specified in the itinerary', 'Personal expenses and tips', 'Camera and photography equipment', 'Early check-in and late check-out unless specified'], 
    '[{"day": 1, "title": "Arrival & Chilaw Wetlands", "highlights": ["Airport welcome", "Chilaw transfer", "Wetland boat safari"], "description": "Airport welcome. Transfer to Chilaw. Afternoon boat safari through the Mundel Lake wetlands."}, {"day": 2, "title": "Chilaw Lagoon Birding", "highlights": ["Dawn birding", "Lagoon exploration", "Migratory species"], "description": "Dawn birding expedition along the Chilaw lagoon. Spot herons, kingfishers, and migratory species."}, {"day": 3, "title": "Wilpattu National Park", "highlights": ["Wilpattu NP", "Leopard territory", "Wilderness camp"], "description": "Transfer to Wilpattu NP. Afternoon safari exploring one of Asia''s oldest wildlife reserves."}, {"day": 4, "title": "Full Day Wilpattu Safari", "highlights": ["Full-day safari", "Sloth bears", "Expert tracker"], "description": "Full-day safari with expert tracker. Search for sloth bears, leopards, and sambar deer."}, {"day": 5, "title": "Journey to the East Coast", "highlights": ["Cross-island drive", "Whale watching", "Dolphin spotting"], "description": "Cross-island drive to Trincomalee. Afternoon whale and dolphin watching excursion."}, {"day": 6, "title": "Pigeon Island Marine Sanctuary", "highlights": ["Pigeon Island", "Reef sharks", "Sea turtles"], "description": "Snorkeling at Pigeon Island, reef sharks, sea turtles, and coral formations."}, {"day": 7, "title": "Coastal Birding & Lagoons", "highlights": ["Kokilai Lagoon", "Flamingos", "Pelicans"], "description": "Visit Kokilai Lagoon, one of Sri Lanka''s premier birding sites. Spot flamingos and pelicans."}, {"day": 8, "title": "Arugam Bay & Kumana", "highlights": ["Kumana NP", "Waterbird nesting", "Lagoon safari"], "description": "Transfer to Arugam Bay. Afternoon safari at Kumana National Park, nesting waterbirds."}, {"day": 9, "title": "Arugam Bay Surf & Nature", "highlights": ["Surf coast", "Crocodiles", "Monitor lizards"], "description": "Morning at leisure in Arugam Bay. Afternoon lagoon boat safari spotting crocodiles and monitor lizards."}, {"day": 10, "title": "Gal Oya Wilderness", "highlights": ["Gal Oya NP", "Boat safari", "Swimming elephants"], "description": "Transfer to Gal Oya National Park. Unique boat safari on Senanayake Samudra, swimming elephants."}, {"day": 11, "title": "Gal Oya Indigenous Walk", "highlights": ["Vedda community", "Forest walk", "Nature photography"], "description": "Guided forest walk with indigenous Vedda community. Afternoon nature photography session."}, {"day": 12, "title": "Into the Mountains", "highlights": ["Horton Plains NP", "World''s End", "Cloud forest"], "description": "Ascend to Nuwara Eliya. Visit Horton Plains National Park and World''s End. Cloud forest exploration."}, {"day": 13, "title": "Highland Birding", "highlights": ["Endemic species", "Highland forests", "Mountain birding"], "description": "Dawn birding in the highland forests, endemic Sri Lanka wood pigeon and yellow-eared bulbul."}, {"day": 14, "title": "Sinharaja Rainforest", "highlights": ["Sinharaja UNESCO", "Rainforest trek", "Bird flocks"], "description": "Transfer to Sinharaja, UNESCO World Heritage rainforest. Trek with expert ornithologist."}, {"day": 15, "title": "Deep Sinharaja Exploration", "highlights": ["Endemic birds", "Rare amphibians", "Pristine forest"], "description": "Full-day rainforest expedition. Search for endemic mixed-species bird flocks and rare amphibians."}, {"day": 16, "title": "Kitulgala Adventure", "highlights": ["White-water rafting", "Kelani River", "Night walk"], "description": "Transfer to Kitulgala. White-water rafting on the Kelani River. Jungle night walk."}, {"day": 17, "title": "Departure", "highlights": ["Final birding", "Airport transfer", "Farewell"], "description": "Morning forest birding walk. Transfer to Colombo airport for departure."}]'::jsonb, 
    ARRAY['/Photos/Other sections/Journey_Velora Wild new.jpg', '/Photos/Other sections/Section 2 _ Wildlife Expedition.jpeg', '/Photos/Other sections/Our Journeys_Wildlife.jpeg', '/Photos/Other sections/Wild life .jpeg', '/Photos/Other sections/Water Rafting Kitulgala.jpg', '/Photos/Other sections/new-8.webp'], 
    true
)
ON CONFLICT (id) DO UPDATE SET
    slug = EXCLUDED.slug,
    category = EXCLUDED.category, title = EXCLUDED.title, location = EXCLUDED.location, days = EXCLUDED.days,
    image_url = EXCLUDED.image_url, tag = EXCLUDED.tag, subtitle = EXCLUDED.subtitle, travel_style = EXCLUDED.travel_style,
    description = EXCLUDED.description, accommodation = EXCLUDED.accommodation, highlights = EXCLUDED.highlights,
    why_special = EXCLUDED.why_special, perfect_for = EXCLUDED.perfect_for, route = EXCLUDED.route,
    route_coords = EXCLUDED.route_coords, included = EXCLUDED.included, not_included = EXCLUDED.not_included,
    itinerary = EXCLUDED.itinerary, gallery_images = EXCLUDED.gallery_images, is_active = EXCLUDED.is_active;

